#!/usr/bin/env bash
# Whole measurement campaign: single-fault recovery tests (3 systems in parallel), the
# random-failure run with kubethanos, and the rolling-update check. About 35 minutes.
#
#   ./measure/run-all.sh                                   # writes to results/ (overwrites it!)
#   RESULTS_DIR=results-rerun ./measure/run-all.sh         # keep an earlier campaign untouched
#   RUNS=1 STS_RUNS=1 CHAOS_SECONDS=60 RESULTS_DIR=results-smoke ./measure/run-all.sh   # ~8 min smoke test
#
# Do not edit this file while it runs: bash reads a script as it executes it.
set -euo pipefail
cd "$(dirname "$0")/.."
export RESULTS_DIR=${RESULTS_DIR:-results}
RUNS=${RUNS:-10}; STS_RUNS=${STS_RUNS:-3}; CHAOS_SECONDS=${CHAOS_SECONDS:-900}
mkdir -p "$RESULTS_DIR"

[ -n "${SKIP_SETUP:-}" ] || ./measure/setup.sh
echo "system,fault,iter,t_kill_ms,recovered,recovery_s,restarts,reset_s" > "$RESULTS_DIR/recovery.csv"
# host clock minus cluster clock [s]; needed to align the kill times (host) with the prober log (cluster)
python3 - > "$RESULTS_DIR/clock_offset_s" <<'PY'
import subprocess, time
out = subprocess.run(["kubectl", "-n", "lws-demo", "exec", "deploy/prober", "--", "python", "-c",
                      "import time; print(time.time())"], capture_output=True, text=True).stdout
print(round(time.time() - 0.03 - float(out.split()[-1]), 2))
PY

echo ">> recovery tests ($RUNS runs for LWS and STS+LP, $STS_RUNS for STS)"
( ./measure/recovery.py lws worker "$RUNS" && ./measure/recovery.py lws leader "$RUNS" ) &
( ./measure/recovery.py sts-lp worker "$RUNS" 180 && ./measure/recovery.py sts-lp leader "$RUNS" 180 ) &
( ./measure/recovery.py sts worker "$STS_RUNS" 60 && ./measure/recovery.py sts leader "$STS_RUNS" 60 ) &
wait

echo ">> random-failure run ($CHAOS_SECONDS s)"
./measure/chaos.sh "$CHAOS_SECONDS"
kubectl -n lws-demo logs deploy/prober > "$RESULTS_DIR/prober.csv"

echo ">> rolling-update check"
./measure/rolling_update.py
echo ">> campaign finished, results are in $RESULTS_DIR/"
